test('failed audio fragments retain FIFO order and retry without losing clips',async()=>{
 let time=0;const recorders=[],tracks={stopped:0,stop(){this.stopped++}};
 class Recorder{static isTypeSupported(){return true}constructor(){this.state='inactive';this.mimeType='audio/webm';recorders.push(this)}start(){this.state='recording'}stop(){if(this.state==='inactive')return;this.state='inactive';time+=1000;this.ondataavailable({data:new Blob(['a'.repeat(1000)],{type:'audio/webm'})});this.onstop();}}
 const h=harness('manager',{MediaRecorder:Recorder,Blob,File,FormData,performance:{now:()=>time},navigator:{mediaDevices:{async getUserMedia(){return {getTracks:()=>[tracks]}}}}});await h.settle();let fail=true,n=0;h.db.functions.invoke=async()=>fail?{error:{message:'offline'}}:{data:{text:'Фрагмент '+(++n)}};
 await h.click('shelf');await h.click('shelf-voice');assert.equal(h.api.recording(),true);
 recorders[0].stop();await h.settle();await h.settle();assert.ok(tracks.stopped>0);assert.match(h.document.body.textContent,/Повторить распознавание · 2/);
 fail=false;await h.click('retry-voice');await h.settle();assert.equal(h.document.querySelector('[data-tr-field="transcript"]').value,'Фрагмент 1 Фрагмент 2');assert.equal(h.api.recording(),false);assert.doesNotMatch(h.document.body.textContent,/Повторить распознавание ·/);
});
