function filter(h,attribute,value){const el=h.document.querySelector('['+attribute+']');if(el.tagName==='SELECT'){for(const o of el.querySelectorAll('option')){o.removeAttribute('selected');if(o.value===value)o.setAttribute('selected','');}}else el.value=value;el.dispatchEvent(new h.window.Event('change',{bubbles:true}));}
